using namespace std;

const int LOG = 20;

vector<vector<int> > g;
vector<vector<int> > up;
vector<int> depth, parent;

// 普通 LCA（基于固定根1）
int lca(int u, int v) {
    if (depth[u] < depth[v]) {
        swap(u, v);
    }

    // 先把 u 提到和 v 同一深度
    int diff = depth[u] - depth[v];
    for (int k = 0; k < LOG; k++) {
        if ((diff >> k) & 1) {
            u = up[k][u];
        }
    }

    if (u == v) {
        return u;
    }

    // 一起向上跳
    for (int k = LOG - 1; k >= 0; k--) {
        if (up[k][u] != up[k][v]) {
            u = up[k][u];
            v = up[k][v];
        }
    }

    return up[0][u];
}

void solve() {
    int T;
    cin >> T;

    while (T--) {
        int n, q;
        cin >> n >> q;

        g.assign(n + 1, vector<int>());
        for (int i = 0; i < n - 1; i++) {
            int x, y;
            cin >> x >> y;
            g[x].push_back(y);
            g[y].push_back(x);
        }

        up.assign(LOG, vector<int>(n + 1, 0));
        depth.assign(n + 1, 0);
        parent.assign(n + 1, 0);

        // 用栈模拟 DFS，避免递归爆栈
        vector<int> stack;
        stack.push_back(1);
        parent[1] = 0;

        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();

            for (int v : g[u]) {
                if (v == parent[u]) {
                    continue;
                }
                parent[v] = u;
                depth[v] = depth[u] + 1;
                stack.push_back(v);
            }
        }

        // 初始化第 0 层祖先
        for (int i = 1; i <= n; i++) {
            up[0][i] = parent[i];
        }

        // 倍增预处理
        for (int k = 1; k < LOG; k++) {
            for (int i = 1; i <= n; i++) {
                up[k][i] = up[k - 1][up[k - 1][i]];
            }
        }

        while (q--) {
            int r, u, v;
            cin >> r >> u >> v;

            int a = lca(u, v);
            int b = lca(u, r);
            int c = lca(v, r);

            // 按结论分类讨论
            if (a == b) {
                cout << c << '\n';
            } else if (a == c) {
                cout << b << '\n';
            } else {
                cout << a << '\n';
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}
